package com.example.order.controller; import com.example.order.model.OrderRequest; import org.springframework.web.bind.annotation.*; import org.springframework.web.client.RestTemplate; import java.util.*; @RestController @RequestMapping("/api/orders") public class OrderController { private final RestTemplate rt=new RestTemplate(); @PostMapping public Map<String,Object> create(@RequestBody OrderRequest r){String base=System.getenv().getOrDefault("INVENTORY_URL","http://localhost:8081"); String u=base+"/api/inventory/"+r.sku()+"/reserve?quantity="+r.quantity(); rt.postForObject(u,null,Object.class); return Map.of("status","CONFIRMED","sku",r.sku(),"quantity",r.quantity());} }
